custom_css:
/* ==========================================================================
 * Instagram Dark OLED Theme for SillyTavern 1.19.1+
 * Design Reference : Figma Instagram UI Screens (Dark Theme 0:21 / 0:156 / 0:262 / 0:561 / 0:643)
 * Locked Spec      : Pure #000000 Canvas + Borderless AI Stream + #262626 User Capsule
 *                    Dialogue Quote #A58C73 + S2 (#3797EF Solid Circle Send Button)
 *                    Typography 1A: Inter Variable + HarmonyOS Sans (woff2 unicode-range)
 * ========================================================================== */

@import url("https://cdn.jsdelivr.net/npm/@fontsource-variable/inter@5.2.5/wght.css");
@import url("https://cdn.jsdelivr.net/npm/@luzixu/harmonyos-sans@0.1.2/wght.css");

/* --------------------------------------------------------------------------
 * 1. 全局设计变量与字体栈 (Global Design Tokens & Font Locks)
 * -------------------------------------------------------------------------- */
:root {
    --mainFontFamily: "Inter Variable", "HarmonyOS Sans", "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei UI", system-ui, -apple-system, sans-serif;
    --monoFontFamily: "JetBrains Mono", "Cascadia Code", "SFMono-Regular", Consolas, "Liberation Mono", Menlo, monospace;

    /* Instagram Dark (Figma 0:21) 扩展设计语义 Token */
    --ig-bg-canvas: #000000;
    --ig-bg-chrome: #121212;
    --ig-bg-subbar: #0A0A0A;
    --ig-bg-elevated: #262626;
    --ig-bg-card: #161618;
    --ig-bg-input: #0A0A0C;
    --ig-text-primary: #F9F9F9;
    --ig-text-prose: #E2E2E6;
    --ig-text-quote: #A58C73;
    --ig-text-action: #9898A0;
    --ig-text-muted: #8E8E93;
    --ig-accent-blue: #3797EF;
    --ig-accent-blue-hover: #4AA3F5;
    --ig-accent-blue-active: #2684DC;
    --ig-border-chrome: rgba(255, 255, 255, 0.14);
    --ig-border-chip: rgba(255, 255, 255, 0.15);
    --ig-border-input: rgba(255, 255, 255, 0.20);
    --ig-border-pill: rgba(255, 255, 255, 0.38);
    --ig-divider-subtle: rgba(60, 60, 67, 0.29);

    /* 修正 #3797EF 蓝底复选框对勾为纯白 (#17 防坑点 4) */
    --SmartThemeCheckboxTickColor: #FFFFFF !important;
}

html,
body {
    color-scheme: dark !important;
    background-color: var(--ig-bg-canvas) !important;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    text-rendering: optimizeLegibility;
}

/* 保护 FontAwesome 图标字体不被全局字体干扰 */
.fa,
.fas,
.fa-solid {
    font-family: "Font Awesome 6 Free", "Font Awesome 5 Free", "FontAwesome" !important;
    font-weight: 900;
}

.far,
.fa-regular {
    font-family: "Font Awesome 6 Free", "Font Awesome 5 Free", "FontAwesome" !important;
}

.fab,
.fa-brands {
    font-family: "Font Awesome 6 Brands", "Font Awesome 5 Brands", "FontAwesome" !important;
    font-weight: 400;
}

/* 锁定代码块、正则脚本与自定义 CSS 编辑框为等宽字体 */
code,
pre,
.mes_text code,
.mes_text pre,
#regex_container textarea,
#customCSS,
.monospace {
    font-family: var(--monoFontFamily) !important;
}

/* 全局现代极细暗色滚动条 (消除默认 11px 亮灰滚动条眩光) */
::-webkit-scrollbar {
    width: 5px;
    height: 5px;
}

::-webkit-scrollbar-track {
    background: transparent;
}

::-webkit-scrollbar-thumb {
    background-color: rgba(255, 255, 255, 0.18);
    border-radius: 999px;
}

::-webkit-scrollbar-thumb:hover {
    background-color: rgba(255, 255, 255, 0.32);
}

/* --------------------------------------------------------------------------
 * 2. 画布背景层与常驻双顶栏 (#bg1 / #top-bar / #extensionTopBar)
 * -------------------------------------------------------------------------- */
#bg1 {
    background-color: var(--ig-bg-canvas);
}

/* 当用户未来启用非透明角色立绘壁纸时，自动叠加纯黑暗角渐晕保障白字锐利度 */
#bg1:not([style*="__transparent.png"]):not([style*="none"])::after {
    content: "";
    position: absolute;
    inset: 0;
    pointer-events: none;
    background: linear-gradient(
        180deg,
        rgba(0, 0, 0, 0.62) 0%,
        rgba(0, 0, 0, 0.86) 48%,
        rgba(0, 0, 0, 0.95) 100%
    );
}

#sheld {
    background-color: transparent;
}

/* 主顶栏 (Figma 0:128 #121212 Chrome Surface) */
body.no-blur #top-bar,
#top-bar,
#top-settings-holder {
    background-color: var(--ig-bg-chrome) !important;
    border-bottom: 1px solid rgba(255, 255, 255, 0.12);
    box-shadow: none;
}

#top-settings-holder .drawer-icon {
    color: var(--ig-text-muted);
    opacity: 1;
    transition: color 0.15s ease, transform 0.12s ease;
}

#top-settings-holder .drawer-icon:hover {
    color: #D4D4D8;
}

#top-settings-holder .drawer-icon.openIcon {
    color: var(--ig-text-primary);
    filter: drop-shadow(0 0 6px rgba(55, 151, 239, 0.35));
}

/* 顶部第二栏 Extension-TopInfoBar 常驻微阶梯融黑 (#0A0A0A，覆盖后加载扩展圆角与边框) */
#extensionTopBar {
    background-color: var(--ig-bg-subbar) !important;
    border: none !important;
    border-bottom: 1px solid rgba(255, 255, 255, 0.10) !important;
    border-radius: 0 !important;
    color: var(--ig-text-action);
}

#extensionConnectionProfiles {
    background-color: var(--ig-bg-chrome) !important;
    border: 1px solid var(--ig-border-chip) !important;
    border-radius: 6px !important;
    color: var(--ig-text-primary) !important;
}

/* --------------------------------------------------------------------------
 * 3. 聊天阅读流：#000000 无框 AI 叙事 + #262626 玩家深灰胶囊 + Q1 排版语义
 * -------------------------------------------------------------------------- */
#chat {
    background-color: var(--SmartThemeChatTintColor);
    border-color: rgba(255, 255, 255, 0.08);
}

#chat .mes {
    background-color: transparent;
    border-bottom: 1px solid var(--ig-divider-subtle);
    padding-top: 12px;
    padding-bottom: 12px;
}

#chat .mes.last_mes {
    border-bottom: none;
}

#chat .mes.selected {
    background-color: rgba(55, 151, 239, 0.14);
}

/* 角色名与弱化元数据 (Figma 0:26 & 0:43) */
.ch_name .name_text {
    color: var(--ig-text-primary);
    font-weight: 600;
    letter-spacing: -0.01em;
}

.mes .timestamp,
.mes .mesIDDisplay,
.mes .mes_timer,
.mes .tokenCounterDisplay {
    color: var(--ig-text-muted);
    opacity: 0.72;
    font-weight: 400;
}

.mesAvatarWrapper .avatar {
    box-shadow: 0 0 0 1px rgba(255, 255, 255, 0.10);
}

/* 玩家发言深灰圆角胶囊 (#17 防坑点 2：适配 chat_display:0 扁平模式) */
#chat .mes[is_user="true"] .mes_block {
    background-color: var(--SmartThemeUserMesBlurTintColor); /* #262626 */
    border: 1px solid rgba(255, 255, 255, 0.07);
    border-radius: 16px;
    padding: 10px 14px;
    margin-top: 2px;
    margin-bottom: 2px;
}

#chat .mes[is_user="true"] .mes_text {
    color: #ECECEF;
    padding-right: 0;
    padding-bottom: 2px;
}

#chat .mes[is_user="true"] .mes_text q {
    color: #BC9F82;
}

/* RP 正文排版与暖棕金台词分层 (清透柔白旁白 #E2E2E6 + 台词 #A58C73 + 动作 #9898A0；保护酒馆助手卡片) */
.mes_text {
    color: var(--ig-text-prose); /* #E2E2E6 清爽冷柔白 */
    font-weight: 375;
    line-height: 1.72;
    letter-spacing: 0.015em;
    line-break: strict;
}

.mes_text p {
    margin-top: 0;
    margin-bottom: 0.78em;
}

.mes_text p:last-child {
    margin-bottom: 0;
}

/* 引号人物对话台词：#A58C73 温润拿铁棕金 + 420 字重 (SillyTavern 原生自动包裹中英文引号为 <q>) */
.mes_text q {
    color: var(--SmartThemeQuoteColor); /* #A58C73 */
    font-weight: 420;
    font-style: normal;
}

/* 带 *星号* 的动作与心理描写：#9898A0 中性冷灰 + 取消中文伪斜体 (豁免 fa 图标) */
.mes_text em,
.mes_text i:not([class*="fa-"]) {
    color: var(--SmartThemeEmColor); /* #9898A0 */
    font-style: normal;
    font-weight: 375;
}

.mes_text strong,
.mes_text b {
    color: #FFFFFF;
    font-weight: 600;
}

.mes_text a {
    color: var(--ig-accent-blue);
    text-decoration: none;
}

.mes_text a:hover {
    text-decoration: underline;
}

.mes_text blockquote {
    border-left: 2px solid rgba(255, 255, 255, 0.22);
    background-color: rgba(255, 255, 255, 0.03);
    color: #C7C7CC;
    padding: 6px 12px;
    margin: 8px 0;
    border-radius: 0 6px 6px 0;
}

/* 代码块与行内代码 */
.mes_text pre {
    background-color: var(--ig-bg-chrome);
    border: 1px solid rgba(255, 255, 255, 0.12);
    border-radius: 8px;
    padding: 10px 12px;
    color: #DCDCE2;
    overflow-x: auto;
}

.mes_text :not(pre) > code {
    background-color: #1C1C1F;
    border: 1px solid rgba(255, 255, 255, 0.12);
    border-radius: 4px;
    padding: 1px 5px;
    color: var(--ig-text-primary);
}

/* 思考链 <think> 折叠块静默降噪 */
.mes_reasoning_details {
    background-color: #0B0B0D;
    border: 1px solid rgba(255, 255, 255, 0.08);
    border-left: 2px solid rgba(255, 255, 255, 0.20);
    border-radius: 8px;
    padding: 4px 10px;
    margin: 4px 0 8px 0;
}

.mes_reasoning_header {
    color: var(--ig-text-muted);
    font-size: 0.86em;
    font-weight: 400;
}

.mes_reasoning {
    color: var(--ig-text-muted);
    font-size: 0.90em;
    font-weight: 375;
    line-height: 1.65;
    padding-top: 4px;
}

/* 酒馆助手 / 前端卡片 Iframe 跨帧透明暗黑合成保护 (消除 Chromium color-scheme 跨帧白角漏底) */
.mes_text iframe,
.TH-render,
.TH-render iframe {
    background: transparent !important;
    background-color: transparent !important;
    color-scheme: dark !important;
    border: none;
}

/* 消息内原生 <details> 折叠块 (兼容预设中的背景剧情/内心折叠标签) */
.mes_text details:not(.mes_reasoning_details) {
    background-color: #121214;
    border: 1px solid rgba(255, 255, 255, 0.12);
    border-radius: 10px;
    padding: 6px 12px;
    margin: 6px 0;
}

.mes_text details:not(.mes_reasoning_details) > summary {
    color: var(--ig-text-primary);
    font-size: 0.92em;
    font-weight: 600;
    cursor: pointer;
    user-select: none;
}

.mes_text details:not(.mes_reasoning_details)[open] > summary {
    margin-bottom: 6px;
    padding-bottom: 5px;
    border-bottom: 1px solid rgba(255, 255, 255, 0.08);
}

/* --------------------------------------------------------------------------
 * 4. 底部输入区：Figma 0:573 Send Message 胶囊 + S2 实心蓝圆发送键 + QR 描边芯片
 * -------------------------------------------------------------------------- */
#form_sheld {
    background-color: var(--ig-bg-canvas);
}

/* #17 防坑点 1：覆盖 toggle-dependent.css 中 body.no-blur #send_form !important */
body.no-blur #send_form,
#send_form {
    background-color: var(--ig-bg-canvas) !important;
    border: none !important;
    border-top: 1px solid var(--ig-divider-subtle) !important;
    border-radius: 0 !important;
    box-shadow: none !important;
    padding: 4px 8px 6px 8px;
}

#nonQRFormItems {
    align-items: center;
    column-gap: 10px;
    padding: 2px 2px;
}

#leftSendForm {
    align-items: center;
    gap: 4px;
    flex-wrap: nowrap;
}

#rightSendForm {
    align-items: center;
    gap: 6px;
    flex-wrap: nowrap;
}

#leftSendForm #quickPersona img,
#leftSendForm .avatar {
    width: 30px;
    height: 30px;
    max-width: 30px;
    max-height: 30px;
    border-radius: 50%;
    object-fit: cover;
}

/* #17 防坑点 3：重置 clip-path 与 resize 手柄，防止胶囊圆弧与上沿细描边被破坏 */
#send_textarea {
    clip-path: none !important;
    resize: none !important;
    background-color: var(--ig-bg-canvas) !important;
    border: 1px solid var(--ig-border-pill) !important;
    border-radius: 22px !important;
    color: #FFFFFF !important;
    padding: 8px 14px !important;
    min-height: 38px;
    max-height: 32dvh;
    line-height: 1.45;
    box-shadow: none !important;
    transition: border-color 0.16s ease, background-color 0.16s ease;
}

#send_textarea::placeholder {
    color: var(--ig-text-muted) !important;
    opacity: 1;
}

#send_textarea:focus {
    background-color: var(--ig-bg-chrome) !important;
    border-color: var(--ig-accent-blue) !important;
    outline: none !important;
}

/* 左侧与次级发送栏图标降噪 */
#leftSendForm > div,
#rightSendForm > div:not(#send_but):not(#mes_stop) {
    color: var(--ig-text-muted);
    opacity: 0.88;
    transition: color 0.15s ease, opacity 0.15s ease;
}

#leftSendForm > div:hover,
#rightSendForm > div:not(#send_but):not(#mes_stop):hover {
    color: var(--ig-text-primary);
    opacity: 1;
    filter: none;
}

/* S2 拍板方案：#3797EF Instagram 蓝实心正圆发送主按钮 (不干扰 .displayNone 显隐) */
#rightSendForm #send_but {
    width: 36px;
    height: 36px;
    min-width: 36px;
    min-height: 36px;
    border-radius: 50% !important;
    background-color: var(--ig-accent-blue) !important;
    color: #FFFFFF !important;
    opacity: 1 !important;
    font-size: 15px;
    align-self: center;
    box-shadow: 0 1px 5px rgba(55, 151, 239, 0.32);
    transition: background-color 0.15s ease, transform 0.12s ease !important;
}

#rightSendForm #send_but:hover {
    background-color: var(--ig-accent-blue-hover) !important;
    filter: none !important;
}

#rightSendForm #send_but:active {
    background-color: var(--ig-accent-blue-active) !important;
    transform: scale(0.93);
}

/* 生成中停止按钮 (#mes_stop) 圆钮态 */
#send_form #mes_stop {
    width: 36px;
    height: 36px;
    min-width: 36px;
    min-height: 36px;
    padding: 0;
    border-radius: 50% !important;
    background-color: var(--ig-bg-elevated) !important;
    border: 1px solid rgba(255, 255, 255, 0.22) !important;
    color: var(--ig-text-primary) !important;
    opacity: 1 !important;
    place-content: center;
    text-align: center;
    line-height: 34px;
    align-self: center;
}

#send_form #mes_stop:hover {
    background-color: #333338 !important;
}

/* Quick Reply 快捷回复栏：Figma 0:268 (#000000 底 + 0.15 细白描边芯片) */
#qr--bar {
    opacity: 1 !important;
    padding: 3px 2px 5px 2px;
}

#qr--bar > .qr--buttons .qr--button,
#qr--popout > .qr--body > .qr--buttons .qr--button {
    background-color: var(--ig-bg-canvas) !important;
    border: 1px solid var(--ig-border-chip) !important;
    border-radius: 7px !important;
    color: var(--ig-text-primary) !important;
    font-size: 12.5px;
    font-weight: 500;
    min-height: 28px;
    padding: 3px 10px;
    margin: 2px 0;
    white-space: nowrap;
    transition: background-color 0.14s ease, border-color 0.14s ease;
}

#qr--bar > .qr--buttons .qr--button:hover,
#qr--bar > .qr--buttons .qr--button:active,
#qr--popout > .qr--body > .qr--buttons .qr--button:hover {
    background-color: var(--ig-bg-elevated) !important;
    border-color: rgba(255, 255, 255, 0.28) !important;
}

/* --------------------------------------------------------------------------
 * 5. 抽屉、折叠卡片 L0-L4 边界体系与 PC 工作台表单 (Figma 0:156 / 0:643)
 * -------------------------------------------------------------------------- */
/* L0 外层抽屉与弹窗深邃底座 (#0D0D0F + 清晰 0.16 微光外框 + 立体悬浮阴影) */
.drawer-content,
#character_popup,
#world_popup {
    background-color: #0D0D0F !important;
    border: 1px solid rgba(255, 255, 255, 0.16) !important;
    box-shadow: 0 14px 38px rgba(0, 0, 0, 0.85) !important;
    color: var(--ig-text-primary);
}

.popup,
dialog.popup,
#left-nav-panel,
#right-nav-panel {
    background-color: #0D0D0F !important;
    border-color: rgba(255, 255, 255, 0.16) !important;
    color: var(--ig-text-primary);
}

/* 扩展面板左右双栏间距拓宽 (告别原生 5px 紧贴) */
.extensions_block {
    gap: 12px !important;
    padding: 2px !important;
}

/* L1 折叠卡片外框与嵌套子卡片 (.inline-drawer) */
.inline-drawer {
    background-color: #151518 !important;
    border: 1px solid rgba(255, 255, 255, 0.15) !important;
    border-radius: 10px !important;
    margin-bottom: 10px !important;
    overflow: hidden;
    box-sizing: border-box;
}

.inline-drawer .inline-drawer {
    background-color: #0F0F12 !important;
    border: 1px solid rgba(255, 255, 255, 0.12) !important;
    border-radius: 8px !important;
    margin: 8px 0 !important;
}

/* L2 折叠卡片表头 (彻底清除原生 348deg 灰白/棕黄高光渐变污渍) */
.inline-drawer > .inline-drawer-header,
#extensions_settings .inline-drawer > .inline-drawer-toggle.inline-drawer-header,
#extensions_settings2 .inline-drawer > .inline-drawer-toggle.inline-drawer-header,
.inline-drawer > .standoutHeader.inline-drawer-header {
    background-image: none !important;
    background-color: #1D1D21 !important;
    border: none !important;
    border-radius: 0 !important;
    margin: 0 !important;
    padding: 9px 12px !important;
    filter: none !important;
    transition: background-color 0.15s ease;
}

.inline-drawer > .inline-drawer-header:hover,
#extensions_settings .inline-drawer > .inline-drawer-toggle.inline-drawer-header:hover,
#extensions_settings2 .inline-drawer > .inline-drawer-toggle.inline-drawer-header:hover,
.inline-drawer > .standoutHeader.inline-drawer-header:hover {
    background-color: #242429 !important;
    filter: none !important;
}

/* 独立分区小横幅 (非 .inline-drawer 内部表头的 .standoutHeader / h4) */
.standoutHeader:not(.inline-drawer-header),
#user-settings-block h4:not(.inline-drawer-header) {
    background-image: none !important;
    background-color: #1B1B1F !important;
    border: 1px solid rgba(255, 255, 255, 0.13) !important;
    border-radius: 8px !important;
    padding: 6px 12px !important;
    filter: none !important;
}

/* L3 展开内容区呼吸留白与表头分割微线 */
.inline-drawer > .inline-drawer-content {
    background-color: #131316 !important;
    border: none !important;
    border-top: 1px solid rgba(255, 255, 255, 0.10) !important;
    border-radius: 0 !important;
    padding: 12px !important;
    box-sizing: border-box;
}

.standoutHeader:not(.inline-drawer-header) ~ .inline-drawer-content {
    background-color: #131316 !important;
    border: 1px solid rgba(255, 255, 255, 0.12) !important;
    border-radius: 8px !important;
    padding: 12px !important;
    margin-top: 6px !important;
    box-sizing: border-box;
}

/* 抽屉与面板内部清晰分割线 */
.drawer-content hr,
.inline-drawer-content hr,
.popup hr {
    background-image: none !important;
    background-color: rgba(255, 255, 255, 0.10) !important;
    opacity: 1 !important;
    height: 1px !important;
    margin: 12px 0 !important;
    border: 0 !important;
}

/* L4 正则脚本条目卡片、开关蓝与世界书条目边界 (覆盖后加载的 regex/style.css) */
.regex_settings .flex-container {
    gap: 6px;
}

#global_scripts_block,
#preset_scripts_block,
#scoped_scripts_block {
    padding: 4px 0;
}

.regex-script-label {
    background-color: #0A0A0D !important;
    border: 1px solid rgba(255, 255, 255, 0.14) !important;
    border-radius: 8px !important;
    padding: 7px 10px !important;
    margin: 6px 0 !important;
    align-items: center !important;
    transition: background-color 0.14s ease, border-color 0.14s ease;
}

.regex-script-label:hover {
    background-color: #101014 !important;
    border-color: rgba(255, 255, 255, 0.28) !important;
}

.regex-toggle-on {
    color: var(--ig-accent-blue) !important;
}

.world_entry {
    background-color: #141417;
    border: 1px solid rgba(255, 255, 255, 0.13);
    border-radius: 8px;
    padding: 8px 10px;
    margin-bottom: 8px;
}

/* 表单输入框与下拉框 (Figma 0:169: 深底 + 0.20 细描边 + #3797EF 聚焦边；豁免 Select2 内联搜索框) */
input.text_pole,
textarea.text_pole,
select.text_pole,
.drawer-content input[type="text"]:not(.select2-search__field),
.drawer-content input[type="number"],
.drawer-content input[type="search"]:not(.select2-search__field),
.drawer-content textarea:not(#send_textarea):not(.select2-search__field),
.drawer-content select,
