/* --------------------------------------------------------------------------
 * 6. 移动端专属沉浸 RP 优化层 (严格对齐 ST 真实断点 <=1000px / <=450px)
 *    PC 端 (>1000px) 完全不受此层影响，100% 保留多栏并排与高密度工作台
 * -------------------------------------------------------------------------- */
@media screen and (max-width: 1000px) {
    /* 释放 #chat 横向黄金阅读宽度：去除侧边框与 11px 固定滚动条槽 */
    #chat {
        border-left: none !important;
        border-right: none !important;
        scrollbar-width: none;
        scrollbar-gutter: auto !important;
        padding-left: 0;
        padding-right: 0;
    }

    #chat::-webkit-scrollbar {
        display: none;
        width: 0;
    }

    /* 消息块重构：父子定位安全解耦 — 微缩 .avatar 绝对置顶左上角，.mesAvatarWrapper 流式落位左下角承载 #楼层/耗时/Token */
    #chat .mes:not(.smallSysMes) {
        display: flex;
        flex-direction: column;
        align-items: stretch;
        position: relative;
        padding: 12px 14px;
    }

    #chat .mes:not(.smallSysMes) > .mes_block {
        order: 1;
    }

    /* 默认全关或全空时严格 0 高度、0 边距，覆盖 style.css:1415 .last_mes .mesAvatarWrapper 底部大留白 */
    #chat .mes:not(.smallSysMes) > .mesAvatarWrapper {
        position: static;
        order: 2;
        display: flex;
        flex-direction: row;
        align-items: center;
        gap: 8px;
        width: auto;
        min-width: 0;
        height: auto;
        min-height: 0;
        margin: 0;
        padding: 0 !important;
    }

    /* 仅当至少存在 1 项「开关已开启 且 文本非空」的指标时，才赋予底部横条上间距 */
    body:not(.no-mesIDDisplay) #chat .mes:not(.smallSysMes) > .mesAvatarWrapper:has(> .mesIDDisplay:not(:empty)),
    body:not(.no-timer) #chat .mes:not(.smallSysMes) > .mesAvatarWrapper:has(> .mes_timer:not(:empty)),
    body:not(.no-tokenCount) #chat .mes:not(.smallSysMes) > .mesAvatarWrapper:has(> .tokenCounterDisplay:not(:empty)) {
        margin-top: 6px;
    }

    /* 将左上角微缩头像绝对定位直接挂载到子元素 .avatar 上 (以 .mes 为定位祖先，像素坐标 100% 零偏移) */
    #chat .mes:not(.smallSysMes) > .mesAvatarWrapper > .avatar {
        position: absolute;
        top: 12px;
        left: 14px;
        width: 28px !important;
        height: 28px !important;
        min-width: 28px !important;
        min-height: 28px !important;
        margin: 0;
        z-index: 2;
    }

    #chat .mes:not(.smallSysMes) > .mesAvatarWrapper > .avatar img {
        width: 28px !important;
        height: 28px !important;
        min-width: 28px !important;
        min-height: 28px !important;
        object-fit: cover;
    }

    /* 左下角三项指标排版 (#楼层 / 耗时 / Token数；不加 display !important 以尊重原生开关类) */
    #chat .mes:not(.smallSysMes) > .mesAvatarWrapper > :is(.mesIDDisplay, .mes_timer, .tokenCounterDisplay):empty {
        display: none;
    }

    #chat .mes:not(.smallSysMes) > .mesAvatarWrapper > :is(.mesIDDisplay, .mes_timer, .tokenCounterDisplay) {
        font-size: 11.5px;
        line-height: 1.2;
        font-weight: 400;
        color: var(--ig-text-muted);
        opacity: 0.78;
        font-variant-numeric: tabular-nums;
        text-align: left;
        margin: 0;
        padding: 0;
        white-space: nowrap;
    }

    #chat .mes:not([is_user="true"]) .mes_block {
        padding-left: 0 !important;
        width: 100% !important;
    }

    #chat .mes:not(.smallSysMes):not([is_user="true"]) .ch_name {
        padding-left: 36px;
        min-height: 28px;
        align-items: center;
        margin-bottom: 4px;
    }

    /* 玩家胶囊消息移动端内边距保护、头像中心线精准对齐 (cy 误差 <= 1px) 与胶囊左下角指标对齐 */
    #chat .mes[is_user="true"] .mes_block {
        padding: 10px 14px !important;
        width: 100% !important;
        box-sizing: border-box;
    }

    #chat .mes[is_user="true"]:not(.smallSysMes) > .mesAvatarWrapper > .avatar {
        top: 26px;
        left: 28px;
        width: 26px !important;
        height: 26px !important;
        min-width: 26px !important;
        min-height: 26px !important;
    }

    #chat .mes[is_user="true"]:not(.smallSysMes) > .mesAvatarWrapper > .avatar img {
        width: 26px !important;
        height: 26px !important;
        min-width: 26px !important;
        min-height: 26px !important;
    }

    body:not(.no-mesIDDisplay) #chat .mes[is_user="true"]:not(.smallSysMes) > .mesAvatarWrapper:has(> .mesIDDisplay:not(:empty)),
    body:not(.no-timer) #chat .mes[is_user="true"]:not(.smallSysMes) > .mesAvatarWrapper:has(> .mes_timer:not(:empty)),
    body:not(.no-tokenCount) #chat .mes[is_user="true"]:not(.smallSysMes) > .mesAvatarWrapper:has(> .tokenCounterDisplay:not(:empty)) {
        margin-top: 5px;
        padding-left: 4px !important;
    }

    #chat .mes[is_user="true"]:not(.smallSysMes) .ch_name {
        padding-left: 34px;
        min-height: 28px;
        align-items: center;
        margin-bottom: 4px;
    }

    /* 清除右侧 30px 硬编码留白，赋予移动端 1.08 倍舒适字号与行高 */
    #chat .mes .mes_text {
        padding-right: 0 !important;
        font-size: calc(var(--mainFontSize) * 1.08);
        line-height: 1.75;
    }

    .mes_reasoning_details {
        margin-right: 0;
    }

    .mes_reasoning_details .mes_reasoning_summary {
        margin-right: 0;
    }

    /* 历史消息右上角操作按钮降噪防误触 */
    #chat .mes:not(.last_mes) .mes_buttons {
        opacity: 0.32;
    }

    #chat .mes .mes_buttons:hover,
    #chat .mes .mes_buttons:focus-within {
        opacity: 1;
    }

    #chat .mes .extraMesButtons {
        background-color: #1C1C1F;
        border: 1px solid var(--ig-border-chip);
        border-radius: 14px;
        padding: 3px 6px;
        gap: 6px;
    }

    #chat .mes.last_mes .mes_buttons .mes_button {
        min-width: 28px;
        min-height: 28px;
        display: inline-flex;
        align-items: center;
        justify-content: center;
        border-radius: 8px;
    }

    /* 最新消息底部 Swipe 胶囊化：仅在存在可见分支时预留 52px 底部空间，无分支消息零空洞 */
    #chat .mes.last_mes:is(.swipes_visible, .last_swipe) {
        padding-bottom: 52px !important;
    }

    /* 当带 Swipe 的 .last_mes 同时存在可见左下指标时：保持 position:static (保护 .avatar 定位祖先不偏移)，将指标精准嵌在 < (右缘 58px) 与 1/2 > 之间的 x=68px、垂直中心 bottom=26px 处，且总底高恒定 52px */
    body:not(.no-mesIDDisplay) #chat .mes.last_mes:is(.swipes_visible, .last_swipe):not(.smallSysMes):has(> .mesAvatarWrapper > .mesIDDisplay:not(:empty)),
    body:not(.no-timer) #chat .mes.last_mes:is(.swipes_visible, .last_swipe):not(.smallSysMes):has(> .mesAvatarWrapper > .mes_timer:not(:empty)),
    body:not(.no-tokenCount) #chat .mes.last_mes:is(.swipes_visible, .last_swipe):not(.smallSysMes):has(> .mesAvatarWrapper > .tokenCounterDisplay:not(:empty)) {
        padding-bottom: 9px !important;
    }

    body:not(.no-mesIDDisplay) #chat .mes.last_mes:is(.swipes_visible, .last_swipe):not(.smallSysMes) > .mesAvatarWrapper:has(> .mesIDDisplay:not(:empty)),
    body:not(.no-timer) #chat .mes.last_mes:is(.swipes_visible, .last_swipe):not(.smallSysMes) > .mesAvatarWrapper:has(> .mes_timer:not(:empty)),
    body:not(.no-tokenCount) #chat .mes.last_mes:is(.swipes_visible, .last_swipe):not(.smallSysMes) > .mesAvatarWrapper:has(> .tokenCounterDisplay:not(:empty)) {
        height: 34px;
        margin-top: 9px !important;
        margin-left: 54px !important;
        padding-left: 0 !important;
        align-items: center;
    }

    #chat .mes.last_mes .swipe_left {
        left: 14px;
        bottom: 4px;
        width: 44px;
        height: 44px;
        min-width: 44px;
        min-height: 44px;
        border-radius: 22px;
        background-color: rgba(18, 18, 18, 0.92);
        border: 1px solid var(--ig-border-chip);
        color: var(--ig-text-primary);
        font-size: 14px;
        display: flex;
        align-items: center;
        justify-content: center;
        opacity: 0.90;
    }

    #chat .mes.last_mes .swipeRightBlock {
        right: 14px;
        bottom: 4px;
        flex-direction: row-reverse;
        align-items: center;
        gap: 6px !important;
    }

    #chat .mes.last_mes .swipe_right {
        position: static;
        width: 44px;
        height: 44px;
        min-width: 44px;
        min-height: 44px;
        border-radius: 22px;
        background-color: rgba(18, 18, 18, 0.92);
        border: 1px solid var(--ig-border-chip);
        color: var(--ig-text-primary);
        font-size: 14px;
        display: flex;
        align-items: center;
        justify-content: center;
        opacity: 0.90;
    }

    #chat .mes.last_mes .swipes-counter {
        background-color: rgba(18, 18, 18, 0.92);
        border: 1px solid var(--ig-border-chip);
        border-radius: 13px;
        color: var(--ig-text-primary);
        font-size: 12px;
        font-weight: 500;
        height: 28px;
        min-width: 44px;
        padding: 0 10px;
        margin-bottom: 0;
        align-items: center;
        opacity: 0.92;
    }

    /* 单分支无计数文本时彻底隐藏空胶囊框，并清理非分支态隐形占位盒 */
    #chat .mes .swipes-counter:empty,
    #chat .mes.last_mes .swipes-counter:empty,
    #chat .mes.last_mes:not(.swipes_visible):not(.last_swipe) .swipe_left,
    #chat .mes.last_mes:not(.swipes_visible):not(.last_swipe) .swipeRightBlock:not(:has(.swipes-counter:not(:empty))) {
        display: none !important;
    }

    /* Quick Reply 移动端强制单行丝滑横滑轨道 (零折行占用) */
    #qr--bar,
    #qr--bar.popoutVisible {
        justify-content: flex-start !important;
        overflow-x: auto !important;
        overflow-y: hidden !important;
        scrollbar-width: none;
        -webkit-overflow-scrolling: touch;
        padding: 4px 4px 6px 4px !important;
    }

    #qr--bar::-webkit-scrollbar {
        display: none;
    }

    #qr--bar > .qr--buttons {
        flex-wrap: nowrap !important;
        justify-content: flex-start !important;
        width: max-content !important;
        gap: 6px !important;
    }

    #qr--bar > .qr--buttons .qr--button {
        min-height: 30px;
        min-width: 36px;
        padding: 4px 11px;
        margin: 0;
    }

    /* 底部输入栏紧凑对齐与安全区避让 */
    body.no-blur #send_form,
    #send_form {
        padding: 4px 8px max(8px, env(safe-area-inset-bottom)) 8px !important;
    }

    #nonQRFormItems {
        column-gap: 8px;
    }

    #leftSendForm {
        flex-wrap: nowrap !important;
        align-items: center;
        gap: 2px;
        padding-left: 0;
    }

    #leftSendForm > div {
        width: 30px;
        height: 34px;
        font-size: 16px;
    }

    #leftSendForm #quickPersona img,
    #leftSendForm .avatar {
        width: 24px;
        height: 24px;
        max-width: 24px;
        max-height: 24px;
        border-radius: 50%;
        object-fit: cover;
    }

    #send_textarea {
        font-size: 15px !important;
        padding: 8px 13px !important;
    }

    /* 抽屉面板防滚动穿透、窄屏紧凑内边距与安全区底部留白 (#world_popup 单独解耦防嵌套滚动死锁) */
    .drawer-content,
    #character_popup {
        overscroll-behavior: contain;
        padding: 10px 10px calc(20px + env(safe-area-inset-bottom)) 10px !important;
    }

    #WorldInfo.drawer-content {
        padding: 8px 8px calc(24px + env(safe-area-inset-bottom)) 8px !important;
    }

    /* #world_popup 嵌套于 #WorldInfo.drawer-content 内部：解除 overscroll-behavior: contain 与内层嵌套滚动盒，
     * 统一交由外层 #WorldInfo 全屏丝滑触控滚动（同时兼容 Android Chromium 与 iOS WebKit），并去除冗余外框 */
    #world_popup {
        overscroll-behavior: auto !important;
        overflow-y: visible !important;
        overflow-x: visible !important;
        height: auto !important;
        max-height: none !important;
        margin-top: 0 !important;
        padding: 4px 0 !important;
        border: none !important;
        box-shadow: none !important;
        background-color: transparent !important;
    }

    /* 移动端世界书条目去重框减负：消除 .world_entry 与 .world_entry_form 外层套娃框及双倍内边距，
     * 仅保留内层 .inline-drawer 单层清晰卡片，释放 60px+ 横向宽度确保右侧移动/删除图标 100% 完整露出 */
    #world_popup .world_entry {
        padding: 0 !important;
        margin-bottom: 8px !important;
        border: none !important;
        background-color: transparent !important;
    }

    #world_popup .world_entry_form {
        padding: 0 !important;
        margin: 0 !important;
        border: none !important;
        background-color: transparent !important;
    }

    #world_popup .world_entry .inline-drawer {
        margin-bottom: 0 !important;
    }

    #world_popup .world_entry .inline-drawer > .inline-drawer-header {
        padding: 8px 8px !important;
    }

    #world_popup .world_entry .inline-drawer > .inline-drawer-content {
        padding: 8px !important;
    }

    #world_popup .world_entry select,
    #world_popup .world_entry input.text_pole {
        max-width: 100%;
        min-width: 0;
    }

    .inline-drawer > .inline-drawer-content,
    .standoutHeader:not(.inline-drawer-header) ~ .inline-drawer-content {
        padding: 10px !important;
    }
}

/* 竖屏窄手机断点 (<=450px)：守护非 compact 意外状态下的左右按钮不折行崩坏 */
@media screen and (max-width: 450px) {
    #send_form #leftSendForm,
    #send_form #rightSendForm {
        width: auto;
        flex-wrap: nowrap;
        align-items: center;
    }
}

/* iOS Safari 专属视口、底部 Home 横条避让与世界书嵌套滚动兼容修复 */
@supports (-webkit-touch-callout: none) {
    @media screen and (max-width: 1000px) {
        body:not(.PWA) #send_form {
            padding-bottom: max(10px, env(safe-area-inset-bottom)) !important;
        }

        #world_popup {
            overscroll-behavior: auto !important;
            overflow-y: visible !important;
            height: auto !important;
            max-height: none !important;
            margin-top: 0 !important;
        }
    }
}
